import{_ as t,o as s,c as o,a3 as a}from"./chunks/framework.BTQ4eCVb.js";const u=JSON.parse('{"title":"Tenant API v1 — Assets","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Tenant API v1 — Assets | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/api/tenant-v1-assets"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Tenant API v1 — Assets | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/api/tenant-v1-assets"}]]},"headers":[],"relativePath":"api/tenant-v1-assets.md","filePath":"api/tenant-v1-assets.md","lastUpdated":1787850471000}'),d={name:"api/tenant-v1-assets.md"};function c(i,e,n,r,l,p){return s(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="tenant-api-v1-—-assets" tabindex="-1">Tenant API v1 — Assets <a class="header-anchor" href="#tenant-api-v1-—-assets" aria-label="Permalink to &quot;Tenant API v1 — Assets&quot;">​</a></h1><p>Base path: <code>/api/tenant/v1</code></p><p>Middleware: <code>auth:tenant-api</code>, <code>tenant.user</code>, <code>verified</code>, <code>module:assets</code>, plus permission middleware / policies.</p><p>Assignee scoping: without <code>assets.assign</code> (and not superadmin), list/stats/view/update only include assets where <code>assigned_to</code> is the current user.</p><h2 id="stats" tabindex="-1">Stats <a class="header-anchor" href="#stats" aria-label="Permalink to &quot;Stats&quot;">​</a></h2><h3 id="get-assets-stats" tabindex="-1">GET <code>/assets/stats</code> <a class="header-anchor" href="#get-assets-stats" aria-label="Permalink to &quot;GET `/assets/stats`&quot;">​</a></h3><p>Same filters as list (minus pagination/sort). Payload includes:</p><p><code>total_assets</code>, <code>my_assets</code>, <code>unassigned</code>, <code>active</code>, <code>in_repair</code>, <code>retired</code>, <code>disposed</code>, <code>scope</code> (<code>org</code>|<code>mine</code>).</p><h2 id="assets-crud" tabindex="-1">Assets CRUD <a class="header-anchor" href="#assets-crud" aria-label="Permalink to &quot;Assets CRUD&quot;">​</a></h2><h3 id="get-assets" tabindex="-1">GET <code>/assets</code> <a class="header-anchor" href="#get-assets" aria-label="Permalink to &quot;GET `/assets`&quot;">​</a></h3><p>Query: <code>search</code> (name, number, serial_number, manufacturer, model, location), <code>status</code>, <code>category</code>, <code>assigned_to</code> (<code>unassigned</code> or user id), <code>my_assets</code>, <code>trashed</code>, <code>sort</code>, <code>direction</code>, <code>page</code>, <code>per_page</code>.</p><p>List items include <code>latest_note</code> and nested <code>assignee</code> / <code>creator</code> / optional <code>vendor</code> / optional <code>employee</code>.</p><h3 id="post-assets" tabindex="-1">POST <code>/assets</code> <a class="header-anchor" href="#post-assets" aria-label="Permalink to &quot;POST `/assets`&quot;">​</a></h3><p>Body:</p><table tabindex="0"><thead><tr><th>Field</th><th>Rules</th></tr></thead><tbody><tr><td><code>name</code></td><td>required, string</td></tr><tr><td><code>status</code></td><td><code>active</code> | <code>in_repair</code> | <code>retired</code> | <code>disposed</code> (default <code>active</code>)</td></tr><tr><td><code>category</code></td><td><code>equipment</code> | <code>furniture</code> | <code>vehicle</code> | <code>electronics</code> | <code>software_license</code> | <code>other</code></td></tr><tr><td><code>manufacturer</code>, <code>model</code>, <code>serial_number</code>, <code>location</code></td><td>optional strings</td></tr><tr><td><code>purchased_at</code>, <code>warranty_ends_at</code></td><td>optional dates</td></tr><tr><td><code>purchase_cost</code></td><td>optional numeric</td></tr><tr><td><code>currency</code></td><td>optional, max 3 chars</td></tr><tr><td><code>assigned_to</code></td><td>optional user id (<code>EligibleAssetAssignee</code> — same pool as leads; owners excluded for explicit assign; <code>null</code> clears)</td></tr><tr><td><code>vendor_id</code></td><td>optional; requires Vendors entitled (<code>LinkableVendor</code>)</td></tr><tr><td><code>employee_id</code></td><td>optional; requires Employees entitled (<code>LinkableEmployee</code>)</td></tr></tbody></table><p><code>number</code> is server-generated (<code>AST-</code> + sequence; prefix from <code>assets_number_prefix</code>).</p><h3 id="get-assets-id" tabindex="-1">GET <code>/assets/{id}</code> <a class="header-anchor" href="#get-assets-id" aria-label="Permalink to &quot;GET `/assets/{id}`&quot;">​</a></h3><p>Includes assignee, creator, vendor, employee, notes, and activities. Embedded <code>notes</code> and timeline/domain <code>activities</code> are <strong>newest-first</strong> (<code>created_at</code> DESC, then <code>id</code> DESC).</p><h3 id="put-assets-id" tabindex="-1">PUT <code>/assets/{id}</code> <a class="header-anchor" href="#put-assets-id" aria-label="Permalink to &quot;PUT `/assets/{id}`&quot;">​</a></h3><p>Partial update of asset fields (including soft FKs and <code>assigned_to</code>).</p><h3 id="delete-assets-id" tabindex="-1">DELETE <code>/assets/{id}</code> <a class="header-anchor" href="#delete-assets-id" aria-label="Permalink to &quot;DELETE `/assets/{id}`&quot;">​</a></h3><p>Soft delete. Permission: <code>assets.delete</code>.</p><h3 id="post-assets-id-restore" tabindex="-1">POST <code>/assets/{id}/restore</code> <a class="header-anchor" href="#post-assets-id-restore" aria-label="Permalink to &quot;POST `/assets/{id}/restore`&quot;">​</a></h3><p>Restore a soft-deleted asset. Permission: <code>assets.restore</code>.</p><h3 id="delete-assets-id-force" tabindex="-1">DELETE <code>/assets/{id}/force</code> <a class="header-anchor" href="#delete-assets-id-force" aria-label="Permalink to &quot;DELETE `/assets/{id}/force`&quot;">​</a></h3><p>Permanently delete a soft-deleted asset. Permission: <code>assets.force.delete</code>.</p><h2 id="actions" tabindex="-1">Actions <a class="header-anchor" href="#actions" aria-label="Permalink to &quot;Actions&quot;">​</a></h2><h3 id="post-assets-id-assign" tabindex="-1">POST <code>/assets/{id}/assign</code> <a class="header-anchor" href="#post-assets-id-assign" aria-label="Permalink to &quot;POST `/assets/{id}/assign`&quot;">​</a></h3><p><code>{ &quot;assigned_to&quot;: number|null }</code> — must be an eligible custodian (CRM lead pool) or <code>null</code> to unassign. Workspace owners cannot be selected for explicit assign.</p><h3 id="post-assets-id-notes" tabindex="-1">POST <code>/assets/{id}/notes</code> <a class="header-anchor" href="#post-assets-id-notes" aria-label="Permalink to &quot;POST `/assets/{id}/notes`&quot;">​</a></h3><p><code>{ &quot;body&quot;: string }</code></p><h3 id="get-assets-id-timeline" tabindex="-1">GET <code>/assets/{id}/timeline</code> <a class="header-anchor" href="#get-assets-id-timeline" aria-label="Permalink to &quot;GET `/assets/{id}/timeline`&quot;">​</a></h3><p>Asset activity timeline entries.</p>',33)])])}const m=t(d,[["render",c]]);export{u as __pageData,m as default};
